custom.expression:
let m = p + vec2<f32>(sin(t * 0.6) * 0.15, cos(t * 0.5) * 0.12);
let q = m * vec2<f32>(1.4, 1.1);
let cell = floor(q);
let f = fract(q) - vec2<f32>(0.5, 0.5);
let h = hash(cell);
let h2 = hash(cell + vec2<f32>(7.0, 13.0));
let wob = vec2<f32>(sin(t * 1.1 + h * 6.283), cos(t * 0.9 + h2 * 6.283)) * 0.16;
let d = length(f - wob);
let rad = 0.26 + 0.06 * sin(t * 1.7 + h * 6.283);
let core = pow(1.0 - smoothstep(0.0, rad, d), 1.7);
let turb = cloud(f * 4.0 + vec2<f32>(t * 0.8, -t * 0.6) + h * 3.0);
let fire = core * (0.5 + 0.5 * turb);
let tint = mix(c3, palette(h * 0.7 + t * 0.05 + d * 0.4), 0.4 + 0.25 * turb);
let glow = exp(-d * 3.2) * 0.55 * (0.75 + 0.25 * sin(t * 4.0 + h * 20.0));
let layer1 = tint * fire * 0.75 + c2 * glow * 0.30;
let q2 = q * 1.8 + vec2<f32>(3.7, 2.3);
let cell2 = floor(q2);
let f2 = fract(q2) - vec2<f32>(0.5, 0.5);
let h3 = hash(cell2);
let wob2 = vec2<f32>(cos(t * 1.3 + h3 * 6.283), sin(t * 1.6 + h3 * 3.0)) * 0.2;
let d2 = length(f2 - wob2);
let core2 = 1.0 - smoothstep(0.03, 0.16, d2);
let layer2 = mix(c3, palette(h3 * 0.5 + t * 0.08 + 0.4), 0.4) * core2 * 0.35 + c3 * exp(-d2 * 5.0) * 0.12;
let bgN = cloud(p * 0.6 + vec2<f32>(t * 0.06, t * 0.04));
let bg = mix(c1, c2, 0.25 + 0.35 * bgN) * 0.5;
let ember = stars(p * 2.5 + vec2<f32>(t * 0.05, 0.0), t * 0.8) * 0.18 * (0.5 + 0.5 * sin(t * 2.0 + p.x * 4.0));
return bg + layer1 + layer2 + palette(0.1 + t * 0.02) * ember;
